#include <algorithm>
#include <cstddef>
#include <string>
#include <tuple>
#include <vector>

struct Row { int key; std::string payload; std::size_t order; };

std::vector<Row> Import(std::vector<Row> rows) {
  for (std::size_t i = 0; i < rows.size(); ++i) rows[i].order = i;
  std::sort(rows.begin(), rows.end(),
      [](const Row& a, const Row& b) { return a.key < b.key; });
  auto last = std::unique(rows.begin(), rows.end(),
      [](const Row& a, const Row& b) { return a.key == b.key; });
  rows.erase(last, rows.end());
  std::sort(rows.begin(), rows.end(),
      [](const Row& a, const Row& b) { return a.order < b.order; });
  return rows;
}
